import React, { useState } from 'react';
import AdminSidebar from '../components/AdminSidebar';

const SettingCard = ({ title, description, children }) => (
  <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden mb-6">
    <div className="px-6 py-5 border-b border-gray-50">
      <h3 className="text-sm font-semibold text-gray-900">{title}</h3>
      {description && <p className="text-xs text-gray-400 mt-0.5">{description}</p>}
    </div>
    <div className="px-6 py-6 space-y-5">{children}</div>
  </div>
);

const ChatbotSettingsManager = () => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' });

  const [form, setForm] = useState({
    businessName: 'Gada Electronics',
    supportEmail: 'support@gadaelectronics.com',
    knowledgeBase: 'Example:\n• Refund policy: 7 days return available\n• Delivery time: 3-5 working days\n• Cash on Delivery available\n• Support hours'
  });

  const showToast = (message, type = 'success') => {
    setToast({ show: true, message, type });
    setTimeout(() => setToast({ show: false, message: '', type: 'success' }), 3500);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    // Simulating API save
    setTimeout(() => {
      setSaving(false);
      showToast('Settings saved successfully ✓');
    }, 800);
  };

  return (
    <div className="flex h-screen bg-gray-50 font-display mt-16 overflow-hidden">
      {toast.show && (
        <div className={`fixed top-24 right-4 z-50 p-4 rounded-lg shadow-xl flex items-center gap-3 transition-all duration-300 ${toast.type === 'success' ? 'bg-green-50 text-green-800 border-l-4 border-green-500' : 'bg-red-50 text-red-800 border-l-4 border-red-500'}`}>
          <span className="font-medium text-sm">{toast.message}</span>
        </div>
      )}

      <AdminSidebar isSidebarOpen={isSidebarOpen} setSidebarOpen={setSidebarOpen} />

      <main className="flex-1 overflow-y-auto w-full">
        <form onSubmit={handleSave}>
          <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
            <div className="mb-8">
              <h1 className="text-2xl font-bold text-gray-900 leading-tight">ChatBot Settings</h1>
              <p className="text-sm text-gray-500 mt-1">Manage your AI chatbot knowledge and business details</p>
            </div>

            <SettingCard title="Business Details">
              <input
                type="text"
                name="businessName"
                value={form.businessName}
                onChange={handleChange}
                placeholder="Business Name"
                className="w-full border border-gray-200 rounded-lg py-2.5 px-3 text-sm text-gray-900 outline-none focus:ring-2 focus:ring-gray-900/20 focus:border-gray-900 transition-colors"
              />
              <input
                type="email"
                name="supportEmail"
                value={form.supportEmail}
                onChange={handleChange}
                placeholder="Support Email"
                className="w-full border border-gray-200 rounded-lg py-2.5 px-3 text-sm text-gray-900 outline-none focus:ring-2 focus:ring-gray-900/20 focus:border-gray-900 transition-colors"
              />
            </SettingCard>

            <SettingCard title="Knowledge Base" description="Add FAQs, policies, delivery info, refunds, etc.">
              <textarea
                name="knowledgeBase"
                value={form.knowledgeBase}
                onChange={handleChange}
                rows={8}
                className="w-full border border-gray-200 rounded-lg py-2.5 px-3 text-sm text-gray-900 outline-none focus:ring-2 focus:ring-gray-900/20 focus:border-gray-900 transition-colors resize-y"
              />
            </SettingCard>

            <div>
              <button
                type="submit"
                disabled={saving}
                className="inline-flex items-center px-6 py-2.5 bg-black text-white text-sm font-semibold rounded-lg shadow-sm hover:bg-gray-800 disabled:opacity-50 transition-all cursor-pointer"
              >
                {saving ? 'Saving...' : 'SaveSave'}
              </button>
            </div>
          </div>
        </form>
      </main>
    </div>
  );
};

export default ChatbotSettingsManager;
